# Let me try rotated versions of the 5x5 pattern

original = [
    [3, 3, 3, 3, 3],
    [3, 9, 3, 9, 3],
    [3, 3, 3, 3, 3],
    [3, 9, 3, 9, 3],
    [3, 3, 9, 3, 3]
]

def rotate_90(grid):
    return [list(col[::-1]) for col in zip(*grid)]

def rotate_180(grid):
    return [row[::-1] for row in rotate_90(grid)]

def rotate_270(grid):
    return rotate_90(rotate_90(grid))

# Try rotated versions
print("90° rotation:")
for row in rotate_90(original):
    print(' '.join(map(str, row)))

print("\n180° rotation:")
for row in rotate_180(original):
    print(' '.join(map(str, row)))

print("\n270° rotation:")
for row in rotate_270(original):
    print(' '.join(map(str, row)))

